<?php declare(strict_types=1); require_once __DIR__.'/bootstrap.php';$w=$_SESSION['wizard']??null;if(!$w)redirect('index.php');$common=array_values(array_intersect($w['headers_a'],$w['headers_b']));$known=['Student Name','IC Number','Student ID','Course','Programme','Gender','Email','Phone','Status'];$defaults=array_values(array_intersect($known,$common));?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Map Columns</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/app.css" rel="stylesheet"></head><body><aside class="sidebar"><div class="brand">Student Compare</div><a class="active" href="index.php">Compare</a><a href="history.php">History</a><a href="settings.php">Settings</a></aside><main class="content"><h2>Map Columns</h2><p class="text-secondary">Select fields used to identify the same student. Matching headers are detected automatically.</p><form action="run.php" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="card border-0 shadow-sm"><div class="card-body"><div class="row g-3"><div class="col-md-6"><h5>File A</h5><p><?=e($w['name_a'])?></p><div class="preview"><?=e(implode(' · ',array_slice($w['headers_a'],0,30)))?></div></div><div class="col-md-6"><h5>File B</h5><p><?=e($w['name_b'])?></p><div class="preview"><?=e(implode(' · ',array_slice($w['headers_b'],0,30)))?></div></div></div><hr><label class="form-label fw-bold">Comparison fields</label><div class="row"><?php foreach($common as $f):?><div class="col-md-4 mb-2"><label class="form-check"><input class="form-check-input" type="checkbox" name="rules[]" value="<?=e($f)?>" <?=in_array($f,$defaults,true)?'checked':''?>> <span><?=e($f)?></span></label></div><?php endforeach;?></div><?php if(!$common):?><div class="alert alert-warning">No identical headers were found. Rename the columns so the fields exist in both files.</div><?php endif;?><div class="mt-3" style="max-width:360px"><label class="form-label">Mode</label><select name="mode" class="form-select"><option value="smart" <?=$w['mode']==='smart'?'selected':''?>>Smart Match</option><option value="exact" <?=$w['mode']==='exact'?'selected':''?>>Exact Match</option></select></div><button class="btn btn-primary btn-lg mt-4" <?=!$common?'disabled':''?>>Run Comparison</button></div></div></form></main></body></html>
